  from (values
  ('BIO-0001', 'Botanika', 'Yosunlar, mamırlar, qıjılar, çılpaqtoxumlular', 'qapali', 'Ulotriksdə hansı hüceyrələrin birləşməsindən ziqot əmələ gələr?', NULL::text, '{"A": "qamçısız hüceyrələrin", "B": "dördqamçılı hüceyrələrin", "C": "sporların", "D": "ikiqamçılı hüceyrələrin", "E": "zoosporların"}', 'D', '3', 'Ulotriks yosununda ikiqamçılı hüceyrələrin (qametlərin) birləşməsindən ziqot əmələ gəlir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №1', 'BIO-0001_izah.png'),
  ('BIO-0002', 'Ümumi biologiya', 'Ekologiya və biosfer', 'qapali', 'Ammonyakı nitrit turşusuna qədər oksidləşdirən bakteriyalar hansılardır?', NULL::text, '{"A": "parazit", "B": "fototrof", "C": "nitrifikasiya", "D": "kükürd bakteriyaları", "E": "dəmir bakteriyaları"}', 'C', '3', 'Təbiətdəki nitrifikasiya bakteriyaları ammonyakı nitrit turşusuna oksidləşdirirlər.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №2', 'BIO-0002_izah.png'),
  ('BIO-0003', 'Zoologiya', 'Quşlar və məməlilər', 'qapali', 'Uyğunluğu müəyyən edin. Plasentası → → vardır 2 Döş tilinə malikdir 3 1 → Su → heyvanıdır a. balina b. pinqvin c. yarasa d. ördək e. delfin', 'BIO-0003.png', '{"A": "1 – b, d; 2 – a, e; 3 – c", "B": "1 – a, e; 2 – c, d; 3 – b", "C": "1 – a, e; 2 – c; 3 – b, d", "D": "1 – a, b; 2 – c; 3 – d, e", "E": "1 – c, e; 2 – a; 3 – b, d"}', 'C', '3', 'Balina və delfin plasentaya malik məməli heyvanlar olub, suda yaşayır. Pinqvin və ördək quşlar sinfinə aid olub, döş tilinə malikdir və suda yaşayır. Yarasa isə döş tilinə malik plasentalı məməlidir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №3', 'BIO-0003_izah.png'),
  ('BIO-0004', 'Zoologiya', 'Qurdlar və molyusklar', 'qapali', 'Sxemə əsasən doğru kəsişmələri müəyyən edin. Əsas və aralıq sahibləri onurğalı heyvandır 4 2 1 3 Öküz soliteri Geohelmintdir Əsas və aralıq sahibləri atmosfer havası ilə tənəffüs edir Aralıq sahibində törətdiyi xəstəlik teniarinxozdur', 'BIO-0004.png', '{"A": "1, 3", "B": "2, 3", "C": "1, 4", "D": "2, 4", "E": "3, 4"}', 'A', '3', 'Öküz soliteri sahib dəyişməklə inkişaf etdiyinə görə biohelmintdir. Onun əsas sahibi olan insan və aralıq sahibi olan qaramal onurğalı olub, atmosfer havası ilə tənəffüs edir. Teniarinxoz əsas sahibində törətdiyi xəstəlikdir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №4', 'BIO-0004_izah.png'),
  ('BIO-0006', 'Botanika', 'Örtülütoxumlular şöbəsi', 'qapali', 'Noxud bitkisinin çiçəklərində çiçək düsturundakı struktur elementlərinin sayının cəmi 210-dur. Bu bitkinin hər bir çiçəyində 8 rüşeym kisəsi var. Bu çiçəklərdə maksimum sayda toxumun əmələ gəlməsi üçün ikiqat mayalanmada bilavasitə cəmi neçə hüceyrə iştirak etməlidir?', NULL::text, '{"A": "320", "B": "240", "C": "350", "D": "120", "E": "80"}', 'A', '3', 'Noxud bitkisi paxlalılar fəsiləsinə aid olub, çiçək düsturu K(₅)L₃₊(₂)E(₉)₊₁D₁ kimidir. Onun bir çiçəyində çiçək düsturundakı struktur elementlərinin sayının cəmi 21-dir. Test tapşırığının şərtinə görə 210:21=10 çiçək vardır. Hər bir çiçəyində 8 rüşeym kisəsi olarsa, bu çiçəklərdə cəmi 8x10=80 rüşeym kisəsi olar. İkiqat mayalanmada bir toxumun əmələ gəlməsi üçün hər rüşeym kisəsində bilavasitə 4 hüceyrə (mərkəzi hüceyrə, yumurtahüceyrə və 2 spermi) iştirak edərsə, cəmi 80x4=320 hüceyrə iştirak etməlidir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №6', 'BIO-0006_izah.png'),
  ('BIO-0007', 'Botanika', 'Bakteriyalar və göbələklər', 'qapali', 'Əgər şibyəni əmələ gətirən canlılardan biri ən qədim aləmin nümayəndəsi olarsa, bu şibyə hansı canlıların birgə yaşayışından əmələ gəlmişdir? 1. Hüceyrələrinin quruluşuna görə biri prokariot, digəri isə eukariot olan canlıların 2. Xlorofili fotosintezedici membran üzərində yerləşən canlı ilə əsasən sporla çoxalan canlının 3. Avtotrof yolla qidalanan çoxhüceyrəli canlı ilə bütün növləri yalnız heterotrof yolla qidalanan aləmə aid canlının 4. Plazmidlərə malik canlı ilə xromatofora malik canlının', NULL::text, '{"A": "1, 2", "B": "3, 4", "C": "1, 3", "D": "2, 3", "E": "2, 4"}', 'A', '1', 'Canlıların ən qədim aləmi bakteriyalardır. Deməli, test tapşırığında verilən şibyə sianobakteriya ilə göbələyin birgə yaşayışından ibarətdir. Sianobakteriya prokariot canlı olub xlorofili fotosintezedici membran üzərində yerləşir, onunla birgə yaşayan göbələk isə eukariot canlı olub əsasən sporla çoxalır.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №7', 'BIO-0007_izah.png'),
  ('BIO-0008', 'Ümumi biologiya', 'Seleksiya', 'qapali', 'Sxemə əsasən düzgün kəsişmələri müəyyən edin. Uzaq hibridləşmə zamanı alınan fərdlərdə üzə çıxa bilər Saf xətlərarası çarpazlaşdır- mada üzə çıxa bilər Yalnız bitkilərdə müşahidə olunur İnbridinq nəticəsində alınan fərdlərdə müşahidə olunur Heterozis effekti 1 2 3 4', 'BIO-0008.png', '{"A": "1, 4", "B": "3, 4", "C": "1, 3", "D": "1, 2", "E": "2, 4"}', 'D', '3', 'Heterosiz effekti, heyvanlarda uzaq hibridləşmə zamanı alınan fərdlərdə və saf xətlərarası çarpazlaşdırmada üzə çıxa bilər', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №8', 'BIO-0008_izah.png'),
  ('BIO-0009', 'Botanika', 'Vegetativ orqanlar', 'qapali', 'Eyler-Venn diaqramına əsasən uyğunluğu müəyyən edin. I III II 1. ölü hüceyrələrdən təşkil olunub 2. canlı hüceyrələrdən təşkil olunub 3. ötürücü toxuma qrupuna aiddir 4. əsasən qeyri-üzvi maddələri daşıyır 5. gövdənin qabıq qatında rast gəlinir 6. yarpağın damarlarında rast gəlinir', 'BIO-0009.png', '{"A": "I – 1, 5; II – 2, 6; III – 3, 4", "B": "I – 3, 5; II – 1, 4; III – 2, 6", "C": "I – 2, 6; II – 1, 3; III – 4, 5", "D": "I – 1, 6; II – 2, 3; III – 4, 5", "E": "I – 2, 5; II – 1, 4; III – 3, 6"}', 'E', '3', 'I şəkil ələyəbənzər (floema) borular olub canlı hüceyrələrdən təşkil olunmuşdur və gövdənin qabıq qatında rast gəlinir. II şəkil ksilema boruları olub, ölü hüceyrələrdən təşkil olunmuşdur və əsasən qeyri-üzvi maddələri daşıyır. Hər iki boru ötürücü toxuma qrupuna aid olub yarpağın damarlarında rast gəlinir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №9', 'BIO-0009_izah.png'),
  ('BIO-0010', 'Ümumi biologiya', 'Çoxalma və inkişaf', 'qapali', 'Aşağıdakı proseslərdən hansılar sağlam qadında hamiləliyin üçüncü ayının əvvəlindən başlayaraq baş verir? 1. Rüşeym uşaqlığın divarına yapışır 2. Xovların bir hissəsindən cift əmələ gəlir 3. Rüşeym dövrü başlayır 4. Rüşeymdə ikikameralı ürək yaranır 5. Döl mərhələsi başlayır', NULL::text, '{"A": "3, 5", "B": "1, 4", "C": "2, 4", "D": "2, 5", "E": "1, 3"}', 'D', '3', 'Sağlam qadında hamiləliyin üçüncü ayının əvvəlindən başlayaraq xovların bir hissəsindən cift əmələ gəlir və döl mərhələsi başlayır', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №10', 'BIO-0010_izah.png'),
  ('BIO-0011', 'İnsan anatomiyası və fiziologiyası', 'İfrazat sistemi və dəri', 'qapali', 'Cədvələ əsasən yanlış ifadələri müəyyən edin. Vəzilər Hormonunun çatışmazlığı zamanı əmələ gələn xəstəliklər X miksedema Y akromeqaliya Z şəkərli diabet 1. X vəzisinin ifraz etdiyi hormonlardan birinin çatışmazlığı uşaqlarda ağıl kəmliyinə səbəb ola bilər 2. Öd Z vəzisinin ifraz etdiyi fermentlərin işini fəallaşdırır 3. Y vəzisi “bioloji saat” rolunu oynayan vəzi ilə eyni boşluqda yerləşmir 4. X vəzisinin sintez etdiyi hormonlardan biri kalsitonindir 5. Y vəzisinin ifraz etdiyi hormonlardan biri tiroksindir', 'BIO-0011.png', '{"A": "2, 5", "B": "3, 5", "C": "1, 2", "D": "3, 4", "E": "1, 4"}', 'B', '3', 'X - qalxanabənzər vəzi, Y - hipofiz vəzi, Z - mədəaltı vəzidir. “Bioloji saat” rolunu oynayan vəzi epifiz vəzisidir. O hipofiz vəzi ilə eyni boşluqda-kəllə boşluğunda yerləşir. Tiroksin hormonunu ifraz edən vəzi qalxanabənzər vəzidir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №11', 'BIO-0011_izah.png'),
  ('BIO-0013', 'Ümumi biologiya', 'Mövzulararası əlaqə', 'qapali', 'Hansı xəstəliklərin törədiciləri 8 növ nukleotidə malik ola bilər? 1. qrip 2. vərəm 3. vəba 4. QİÇS 5. çiçək 6. difteriya', 'BIO-0013.png', '{"A": "3, 4, 5", "B": "1, 2, 6", "C": "1, 2, 4", "D": "1, 4, 5", "E": "2, 3, 6"}', 'E', '3', 'Vərəm, vəba və difteriya xəstəliklərinin törədiciləri bakteriyalardır.Bu canlılarda həm DNT, həm də RNT olduğu üçün 8 növ nukleotidə malik ola bilər. Qrip, çiçək və QİÇS xəstəliklərinin törədiciləri viruslardır.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №13', 'BIO-0013_izah.png'),
  ('BIO-0014', 'Botanika', 'Generativ orqanlar', 'qapali', 'Eyler-Venn diaqramına əsasən uyğunluğu müəyyən edin. Lobyanın toxumu Buğdanın toxumu I III II 1. taycıqlardakı yuvalarda yerləşir 2. göbəkciyə malikdir 3. ehtiyat qida maddələri ləpə yarpağı vasitəsi ilə rüşeymə daxil olur 4. bitkinin əsas gövdəsi rüşeym tumurcuğundan inkişaf edir 5. meyvəyanlığı toxum qabığı ilə bitişikdir', 'BIO-0014.png', '{"A": "I – 1, 4; II – 3, 5; III – 2", "B": "I – 2, 4; II – 1, 3; III – 5", "C": "I – 1, 3; II – 2, 4; III – 5", "D": "I – 2, 5; II – 1, 3; III – 4", "E": "I – 1, 2; II – 3, 5; III – 4"}', 'E', '3', 'Lobya bitkisinin meyvəsi paxlameyvə olub, toxumu taycıqlardakı yuvalarda yerləşir və göbəkciyə malikdir. Buğda bitkisinin meyvəsi dənmeyvədir. Onun toxumunda meyvəyanlığı toxum qabığı ilə bitişikdir və ehtiyat qida maddələri ləpə yarpağı vasitəsi ilə rüşeymə daxil olur. Hər iki bitkinin əsas gövdəsi toxumun rüşeym tumurcuğundan inkişaf edir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №14', 'BIO-0014_izah.png'),
  ('BIO-0015', 'Ümumi biologiya', 'Mövzulararası əlaqə', 'qapali', 'Doğru ifadələri müəyyən edin. 1. Somatotrop hormonunun çatışmaması immun reaksiyalarını zəiflədir 2. Adrenalin ürək vurğularının sayını artırır 3. Histidin amin turşusunun çatışmazlığı qanda hemoqlobinin miqdarını artırır 4. Adrenalin qanda qlükozanın miqdarını azaldır 5. A vitamininin çatışmaması faqositlərin funksiyasını zəiflədir', NULL::text, '{"A": "2, 4, 5", "B": "3, 4, 5", "C": "1, 2, 4", "D": "2, 3, 4", "E": "1, 2, 5"}', 'E', '3', 'Hipofiz vəzin ifraz etdiyi somatotrop hormonunun çatışmaması immun reaksiyalarını zəiflədir. Böyrəküstü vəzin hormonu olan adrenalin ürək vurğularının sayını artırır. Orqanizmdə A vitamininin çatışmaması faqositlərin funksiyasını zəiflədir', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №15', 'BIO-0015_izah.png'),
  ('BIO-0016', 'Zoologiya', 'İbtidailər və bağırsaqboşluqlular', 'qapali', 'Şirin su hidrasının bədəni neçə qatdan ibarətdir?', NULL::text, '{"A": "3", "B": "5", "C": "4", "D": "2", "E": "1"}', 'D', '3', 'Şirin su hidrasının bədəni iki qatdan –ektoderma və entodermadan ibarətdir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №16', 'BIO-0016_izah.png'),
  ('BIO-0017', 'İnsan anatomiyası və fiziologiyası', 'Sinir sistemi və analizatorlar', 'qapali', 'İ.P. Pavlova görə görmə analizatorunun 3-cü hissəsi böyük yarımkürələrin hansı payında yerləşir? 1 2 3 4', 'BIO-0017.png', '{"A": "3-təpə payı", "B": "1-təpə payı", "C": "3-ənsə payı", "D": "4-gicgah payı", "E": "2-ənsə payı"}', 'C', '3', 'İ.P. Pavlova görə görmə analizatorunun 3-cü hissəsi baş beyin yarımkürələrinin ənsə payıdır. Bu da 3 rəqəmi ilə işarə olunmuşdur.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №17', 'BIO-0017_izah.png'),
  ('BIO-0018', 'Botanika', 'Bitki aləminin inkişafı', 'qapali', 'Sxemə əsasən X-in yerində yazıla bilməz: X mitoz meyoz mayalanma 1. Söyüdün yaşıl çiçəyi 2. Qarğıdalının qıça çiçək qrupunun çiçəyi 3. Söyüdün sarımtıl çiçəyi 4. Günəbaxanın yalançı dilcikşəkilli çiçəyi 5. Zəncirotunun dilcikşəkilli çiçəyi', 'BIO-0018.png', '{"A": "3, 5", "B": "3, 4", "C": "1, 5", "D": "1, 2", "E": "2, 4"}', 'B', '3', 'Söyüdün sarımtıl çiçəyi bircinsli erkək çiçək olub dişiciyə malik olmadığına görə mayalanma baş vermir, günəbaxanın yalançı dilcikşəkilli çiçəyi erkəkcik və dişiciyə malik olmadığına görə meyoz və mayalanma baş vermir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №18', 'BIO-0018_izah.png'),
  ('BIO-0019', 'İnsan anatomiyası və fiziologiyası', 'Qan, qan dövranı, tənəffüs', 'qapali', 'Ağciyər alveollarında qazlar mübadiləsi zamanı aşağıdakılardan hansı baş vermir?', NULL::text, '{"A": "ağciyər kapilyarlarındakı qanda O₂-nin miqdarının artması", "B": "ağciyər kapilyarlarındakı qanda CO₂-nin miqdarının artması", "C": "O₂-nin alveollardan qana keçməsi", "D": "ağciyər kapilyarlarında venoz qanın arterial qana çevrilməsi", "E": "ağciyər kapilyarlarındakı qanda CO₂-nin miqdarının azalması"}', 'B', '3', 'Ağciyər alveollarında qazlar mübadiləsi zamanı ağciyər kapilyarlarındakı qanda CO₂-nin miqdarının azalması baş verir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №19', 'BIO-0019_izah.png'),
  ('BIO-0020', 'Zoologiya', 'Heyvanlar aləminin inkişafı', 'qapali', 'Cədvələ əsasən doğru fikri müəyyən edin. Xəstəliklər Törədiciləri Keçiriciləri Vəba X Y Leyşmanioz M N Malyariya Z K', 'BIO-0020.png', '{"A": "Z və K eyni aləmə aid ola bilməz", "B": "X və Y eyni aləmə aid ola bilməz", "C": "Y, N, K eyni aləmə aid ola bilməz", "D": "X, M, Z eyni aləmə aid ola bilər", "E": "X və N eyni aləmə aid ola bilər"}', 'B', '3', 'Xəstəliklər Törədiciləri Keçiriciləri Vəba X-bakteriya Y-milçək Leyşmanioz M-leyşmaniya N-mığmığa Malyariya Z-malyariya paraziti K-ağcaqanad X bakteriyalar aləminə, Y, M, N, Z, K isə heyvanlar aləminə aiddir.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №20', 'BIO-0020_izah.png'),
  ('BIO-0021', 'Ümumi biologiya', 'Sitologiya', 'qapali', 'Uyğunluğu müəyyən edin. 1. İnterfaza 2. Profaza 3. Anafaza a. Hüceyrə orqanoidlərinin sayı artır b. Bölünmə vətərləri yaranmağa başlayır c. DNT ikiləşir d. Xromosomların sayı iki dəfə artır e. DNT sapları spirallaşır', NULL::text, '{"A": "1 – a, c; 2 – b, e; 3 – d", "B": "1 – a, e; 2 – c; 3 – b, d", "C": "1 – b, c; 2 – e; 3 – a, d", "D": "1 – d; 2 – b, c; 3 – a, e", "E": "1 – b, c; 2 – a; 3 – d, e"}', 'A', '3', 'İnterfaza mərhələsində hüceyrə orqanoidlərinin sayı artır, DNT ikiləşir. Profaza mərhələsində bölünmə vətərləri yaranmağa başlayır, DNT sapları spirallaşır. Anafaza mərhələsində xromosomların sayı iki dəfə artır.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №21', 'BIO-0021_izah.png'),
  ('BIO-0024', 'Ümumi biologiya', 'Hüceyrənin biokimyası', 'aciq_eded', 'DNT molekulunun bir hissəsində hidrogen rabitələrinin sayı adeninli nukleotidlərin sayı ikiqat hidrogen rabitələrinin sayı üçqat hidrogen rabitələrinin sayı 10000 2000 X Y X+Y cəmini hesablayın.', 'BIO-0024.png', NULL::text, '4000', '3', 'DNT molekulunda A(T) nukleotidlərinin sayı ikiqat hidrogen rabitələrinin sayına, S(Q) nukleotidlərinin sayı isə üçqat hidrogen rabitələrinin sayına bərabərdir. 10000-4000=6000 6000:3=2000 S(Q) Beləliklə bu DNT molekulunun bir hissəsində ikiqat hidrogen rabitələrinin sayı 2000, üçqat hidrogen rabitələrinin sayı 2000 –dir. X+Y=4000', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №24', 'BIO-0024_izah.png'),
  ('BIO-0031', 'Ümumi biologiya', 'Seleksiya', 'qapali', 'Düzgün kəsişmələri müəyyən edin. Arzu olunan əlamətləri möhkəmləndirir Homoziqot genotipli fərdlərin sayını artırır Heteroziqot genotipli fərdlərin sayını artırır Tozcuq dənəsi və rüşeym kisəsi ayrı-ayrı çiçəklərdə əmələ gələn bitkilərdə tətbiq olunur Fərdi seçmə 1 2 3 4', 'BIO-0031.png', '{"A": "1, 2", "B": "3, 4", "C": "2, 3", "D": "1, 4", "E": "1, 3"}', 'A', '3', 'Fərdi seçmə öz-özünə tozlanan bitkilərdə və yaxın qohum çarpazlaşmada heyvanlara tətbiq olunur. Bu yolla saf xətlər alınır. Buna görə də arzu olunan əlamətləri möhkəmləndirir və homoziqot genotipli fərdlərin sayını artırır.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №1', 'BIO-0031_izah.png'),
  ('BIO-0032', 'Botanika', 'Bitki aləminin inkişafı', 'qapali', 'Uyğunluğu müəyyən edin. Adi şamın sarımtıl-yaşıl qozası Qarğıdalının süpürgə çiçək qrupu Darının süpürgə çiçək qrupu 2 1 3 a. tozlanmada iştirak edir b. erkəkcik sapına malikdir c. mayalanma prosesi getmir d. çiçək pulcuğu və çiçək pərdəsinə malikdir e. haploid və diploid xromosom yığımlı hüceyrələrə malikdir', 'BIO-0032.png', '{"A": "1 – a, e; 2 – b, c; 3 – d", "B": "1 – a, c; 2 – b, e; 3 – d", "C": "1 – a, e; 2 – c; 3 – b, d", "D": "1 – a; 2 – c, e; 3 – b, d", "E": "1 – a; 2 – b, c; 3 – d, e"}', 'C', '3', 'Adi şam çılpaqtoxumlular, qarğıdalı və darı bitkiləri isə örtülütoxumlular şöbəsinə aiddir. Adi şam birevli bitki olub, dişi və erkək qozalara malikdir. Erkək qozaları sarımtıl-yaşıl rənglidir və tozcuqlar yalnız tozcuq kisəsində yetişir. Qarğıdalı bircinsli çiçəkləri olan birevli bitkidir. Onun erkək çiçəkləri süpürgə çiçək qrupunda toplanır. Darı birevli bitkidir. Öz-özünə tozlanan ikicinsli çiçəkləri süpürgə çiçək qrupunda toplanır. Qarğıdalı və darının erkəkciyi erkəkcik sapından və tozluqdan ibarətdir. Onların hər üçü tozlanmada iştirak edir və haploid, diploid xromosom yığımlı hüceyrələrə malikdir. Adi şamın erkək qozasında və qarğıdalının süpürgə çiçək qrupunda mayalanma prosesi getmir. Qarğıdalı və darının çiçəkləri çiçək pulcuğu və çiçək pərdəsinə malikdir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №2', 'BIO-0032_izah.png'),
  ('BIO-0033', 'İnsan anatomiyası və fiziologiyası', 'İfrazat sistemi və dəri', 'qapali', 'İnsanda hansı vəzi həm daxili, həm də xarici sekresiya funksiyasını yerinə yetirir?', NULL::text, '{"A": "böyrəküstü", "B": "qalxanabənzər", "C": "hipofiz", "D": "mədəaltı", "E": "timus"}', 'D', '3', 'İnsanda mədəaltı vəzi qarışıq sekresiya vəzisi olaraq həm daxili, həm də xarici sekresiya funksiyasını yerinə yetirir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №3', 'BIO-0033_izah.png'),
  ('BIO-0034', 'Zoologiya', 'Heyvanlar aləminin inkişafı', 'qapali', 'Uyğunluğu müəyyən edin. 1. Ürək boşluğundan yalnız arterial qan keçir 2. Ürək boşluğundan həm venoz, həm də arterial qan keçir 3. Ürək boşluğundan keçən qan nə venoz, nə də arterialdır a. b. c. d. e.', 'BIO-0034.png', '{"A": "1 – b, e; 2 – a, d ; 3 – c", "B": "1 – a; 2 – b; 3 – d, e", "C": "1 – a, b; 2 – d ; 3 – c", "D": "1 – b; 2 – a, d; 3 – c, e", "E": "1 – b; 2 – a, d ; 3 – c"}', 'E', '3', 'Molyusklarda ürək boşluğunda yalnız arterial, quşlar və məməlilərdə həm venoz, həm də arterial qan olur. Həşəratlarda isə qan qazların daşınmasında iştirak etmədiyinə görə qanın ümumiyyətlə arterial və venoz növləri olmur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №4', 'BIO-0034_izah.png'),
  ('BIO-0036', 'İnsan anatomiyası və fiziologiyası', 'Qan, qan dövranı, tənəffüs', 'qapali', 'Sağlam insanın qanında adrenalinin miqdarının (m) zamandan (t) asılı olaraq dəyişməsi qrafiki verilmişdir. t₁–t₂intervalında nə baş verə bilər? m t₁ → t₂ t 1. qan təzyiqi yüksələr 2. ürəyin işi güclənər 3. nəbz vurğularının sayı azalar 4. qlükozanın qanda miqdarı azalar 5. qlükozanın qanda miqdarı artar', 'BIO-0036.png', '{"A": "2, 5", "B": "3, 4", "C": "1, 5", "D": "1, 3", "E": "2, 4"}', 'B', '3', 'Böyrəküstü vəzinin hormonlarından biri olan adrenalinin qanda çoxalması qan təzyiqini yüksəldir, ürəyin işini gücləndirir, nəbz vurğularının sayını, qlükozanın qanda miqdarını artırır. t₁–t₂ intervalında adrenalinin miqdarının azalması isə nəbz vurğularının və qanda qlükozanın miqdarının azalmasına səbəb olur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №6', 'BIO-0036_izah.png'),
  ('BIO-0038', 'Botanika', 'Vegetativ orqanlar', 'qapali', 'Hansı yeraltı şəkildəyişmələrdə təpə və yan tumurcuqları ola bilər? 1 2 3 4', 'BIO-0038.png', '{"A": "1, 2, 4", "B": "2, 3, 4", "C": "1, 2, 3", "D": "yalnız 2, 4", "E": "yalnız 3, 4"}', 'C', '3', '1, 2 və 3 zoğun, 4 isə kökün yeraltı şəkildəyişməsidir. Təpə və yan tumurcuqları hər ikisi birlikdə yalnız zoğun üzərində olduğu üçün cavab 1, 2 və 3-dür.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №8', 'BIO-0038_izah.png'),
  ('BIO-0039', 'Botanika', 'Generativ orqanlar', 'qapali', 'Bitki toxumunun hansı hissəsi (hissələri) ziqotdan əmələ gəlməmişdir? 2 3 4 5', 'BIO-0039.png', '{"A": "1, 4", "B": "yalnız 3", "C": "2, 5", "D": "yalnız 5", "E": "2, 4"}', 'D', '3', '1-tumurcuq, 2-gövdəcik, 3-kökcük və 4-ləpə yarpağıdır. Bunlar rüşeymin hissələri olub, ziqotdan əmələ gəlmişdir. 5- toxum qabığıdır və yumurtacığın divarından əmələ gəlir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №9', 'BIO-0039_izah.png'),
  ('BIO-0040', 'Botanika', 'Yosunlar, mamırlar, qıjılar, çılpaqtoxumlular', 'qapali', 'Yaşıl quş mamırının çoxalmasını əks etdirən sxemdə göstərilən bütün hüceyrələrin xromosom yığımlarının cəmi nəyə bərabərdir? Spor → Protonemanın hüceyrəsi Dişi qametofitin → hüceyrəsi Erkək qametofitin → hüceyrəsi Yumurtahüceyrə → Spermatozoid Ziqot Qutucuq divarı hüceyrəsi', 'BIO-0040.png', '{"A": "16n", "B": "8n", "C": "10n", "D": "12n", "E": "14n"}', 'C', '3', 'Quş mamırının inkişaf mərhələlərindən ziqot, qutucuq və ayaqcıqdan ibarət olan sporofit diploid xromosom yığımına malikdir. Digər hüceyrələr isə haploid xromosom yığımına malikdir. Sxemdə verilən hüceyrələrdən 6-sı haploid, 2-si isə diploiddir. Bu hüceyrələrin xromosom yığımlarının cəmi: 6 1n 2 2n 10n ⋅ +⋅ = olar.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №10', 'BIO-0040_izah.png'),
  ('BIO-0042', 'Ümumi biologiya', 'Sitologiya', 'qapali', 'DNT molekulunda ölçüsü quaninin ölçüsünə bərabər olan azot əsası olmasaydı, “üzünün köçürülməsi” prosesində neçə növ azot əsası iştirak edərdi?', NULL::text, '{"A": "4", "B": "2", "C": "5", "D": "8", "E": "3"}', 'B', '3', 'DNT molekulunda ölçüsü quaninin ölçüsünə bərabər olan azot əsası -adenin olmasaydı, o zaman bu molekulda ona komplementar olan timin azot əsası da olmazdı. Nəticədə “üzünün köçürülməsi” prosesində, yəni transkripsiyada DNT və RNT-nin yalnız quanin və sitozin azot əsasları iştirak edərdi.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №12', 'BIO-0042_izah.png'),
  ('BIO-0044', 'Zoologiya', 'İbtidailər və bağırsaqboşluqlular', 'qapali', 'Şəkildə bağırsaqboşluqlular tipinə aid canlının həyat dövranı əks olunmuşdur. Doğru mülahizəni müəyyən edin.', 'BIO-0044.png', '{"A": "postembrional inkişafı düzünədir", "B": "hermafrodit olan iki fərd çarpaz mayalanmışdır", "C": "1, 4 və 5 diploid hüceyrələrdən təşkil olunmuşdur", "D": "1 və 2 bir hüceyrədən ibarətdir", "E": "3 və 5 bilavasitə planuladan əmələ gəlir"}', 'D', '3', 'Şəkil VII sinfin dərsliyində 67-ci səhifədə verilmişdir. Burada ayrıcinsiyyətli aureliya meduzasının həyat dövranı təsvir olunmuşdur. Bu şəkildə 1-spermatozoid, 2- yumurtahüceyrə olub, bir hüceyrədən ibarətdir. 1 haploid, 4 və 5 isə diploid hüceyrələrdən təşkil olunmuşdur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №14', 'BIO-0044_izah.png'),
  ('BIO-0045', 'Zoologiya', 'Quşlar və məməlilər', 'qapali', 'Şəklə əsasən ön ətrafların qurşaq hissəsinə aid olan sümükləri müəyyən edin. 6 5 4 3 2 1', 'BIO-0045.png', '{"A": "2, 3, 5", "B": "1, 4, 6", "C": "2, 3, 4", "D": "1, 2, 4", "E": "3, 5, 6"}', 'A', '3', 'Quşların ön ətraf qurşağına qarğa, kürək, körpücük sümükləri aiddir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №15', 'BIO-0045_izah.png'),
  ('BIO-0046', 'İnsan anatomiyası və fiziologiyası', 'Həzm və maddələr mübadiləsi', 'qapali', 'Pankreatit xəstəliyi zamanı: 1. mədəaltı vəzinin xarici sekretor funksiyası pozulur 2. mədəaltı vəzinin ifraz etdiyi amilazanın miqdarı artır 3. bağırsaq möhtəviyyatı turş reaksiyalı olur 4. yalnız karbohidratların həzmi pozulur 5. karbohidratların, zülalların, yağların həzmi pozulur 6. əksər hallarda mədə şirəsində pepsinin miqdarı azalır', NULL::text, '{"A": "1, 4, 6", "B": "1, 3, 5", "C": "3, 5, 6", "D": "1, 2, 5", "E": "2, 4, 6"}', 'B', '3', 'Pankreatit xəstəliyi zamanı mədəaltı vəzinin xarici sekretor funksiyası pozulur. Bu zaman onun ifraz etdiyi amilazanın miqdarı azalır. Nəticədə karbohidratların həzmi pozulduğu üçün bağırsaq möhtəviyyatı turş reaksiyalı olur. Mühitin dəyişilməsi zülal və yağların da həzminin pozulmasına səbəb olur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №16', 'BIO-0046_izah.png'),
  ('BIO-0047', 'İnsan anatomiyası və fiziologiyası', 'Sinir sistemi və analizatorlar', 'qapali', 'İnsanın duyğu orqanlarının xəstəliyi deyil: 1. renit 2. enterobioz 3. teniarinxoz 4. sirroz 5. katarakt 6. otoskleroz', 'BIO-0047.png', '{"A": "2, 4, 6", "B": "1, 4, 6", "C": "1, 5, 6", "D": "2, 3, 5", "E": "2, 3, 4"}', 'E', '3', 'İnsanda renit, katarakt, otoskleroz duyğu orqanlarının, enterobioz, teniarinxoz və sirroz isə həzm orqanlarının xəstəlikləridir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №17', 'BIO-0047_izah.png'),
  ('BIO-0048', 'Zoologiya', 'Buğumayaqlılar', 'qapali', 'Yetkin X orqanizmini müəyyən edin. X bığcıqlar xitin borulu sinir sistemi qanda karbon qazı + + – – 1. çay xərçəngi 2. xaçlı hörümçək 3. may böcəyi 4. kəpənək 5. yengəc', 'BIO-0048.png', '{"A": "1, 5", "B": "2, 3", "C": "4, 5", "D": "3, 4", "E": "1, 2"}', 'D', '3', 'Çay xərçəngi və yengəc xitin örtüyə və bığcıqlara malik olsalar da, qanlarında karbon qazı olur. Həşəratların nümayəndələri olan may böcəyi və kəpənəkdə isə bığcıqlar və xitin örtüyü olduğu halda, borulu sinir sistemi olmur. Onların qanı qazlar mübadiləsində iştirak etmədiyi üçün karbon qazı olmur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №18', 'BIO-0048_izah.png'),
  ('BIO-0049', 'İnsan anatomiyası və fiziologiyası', 'Dayaq-hərəkət sistemi', 'qapali', 'İnsan orqanizmində əzələ toxumasının növləri üçün uyğunluğu müəyyən edin. a. işi qeyri – iradidir b. yığılma və boşalma qabiliyyətinə malikdir c. udlaq və qırtlaq əzələləri bu toxumadan təşkil olunmuşdur d. mezoderma mənşəlidir e. işi avtonom sinir sistemi ilə tənzimlənir', 'BIO-0049.png', '{"A": "1 – a, d; 2 – b; 3 – c, e", "B": "1 – a, e; 2 – b, d; 3 – c", "C": "1 – e; 2 – b, d; 3 – a, c", "D": "1 – b, c; 2 – d, e; 3 – a", "E": "1 – b, e; 2 – c; 3 – a, d"}', 'B', '3', 'Birinci şəkildə saya, ikinci şəkildə isə eninəzolaqlı skelet əzələsi toxuması təsvir olunmuşdur. Saya əzələnin işi qeyri – iradidir və avtonom sinir sistemi ilə tənzimlənir, skelet əzələsinin işi iradidir və somatik sinir sistemi ilə tənzimlənir. Udlaq və qırtlaq əzələləri eninəzolaqlı skelet əzələsidir. Əzələ toxumasının hər iki növü mezoderma mənşəli olub, yığılma və boşalma qabiliyyətinə malikdir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №19', 'BIO-0049_izah.png'),
  ('BIO-0050', 'Ümumi biologiya', 'Ekologiya və biosfer', 'qapali', 'Çobanyastığının bal arısı tərəfindən tozlandırılması canlılar arasındakı münasibətlərdən hansına aiddir?', NULL::text, '{"A": "kommensalizm", "B": "parazitizm", "C": "mutualizm", "D": "neytralizm", "E": "amensalizm"}', 'C', '3', 'Çobanyastığının bal arısı tərəfindən tozlandırılması hər iki canlı üçün faydalı münasibət olub, mutualizm adlandırılır.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №20', 'BIO-0050_izah.png'),
  ('BIO-0051', 'Ümumi biologiya', 'Çoxalma və inkişaf', 'qapali', 'Cinsi çoxalmada əmələ gələn hansı canlının genotipi yalnız ana fərdin qametinin genotipi ilə eyni olar?', NULL::text, '{"A": "çöl göyərçininin", "B": "xanı balığının", "C": "yexidnanın", "D": "adadovşanının", "E": "erkək bal arısının"}', 'E', '3', 'Erkək bal arısının əmələ gəlməsində yalnız ana fərdin qameti-yumurtahüceyrəsi iştirak etdiyi üçün, ana fərdin qametinin genotipi ilə erkək bal arısının genotipi eyni olacaq.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №21', 'BIO-0051_izah.png'),
  ('BIO-0052', 'Ümumi biologiya', 'Çoxalma və inkişaf', 'qapali', 'Hansı müddəaları normal inkişaf edən altı aylıq qız uşağına aid etmək olar? 1. Yumurtalıqlarında yetişməmiş yumurtahüceyrələr olur 2. İnkişafının postembrional dövrü embrional dövründən uzundur 3. Süd dişləri çıxmağa başlayır 4. Böyük azı dişləri çıxmağa başlayır 5. Qarışıq sekresiya vəzilərinə malikdir 6. Yasli dövrünü keçirir', NULL::text, '{"A": "1, 3, 5", "B": "1, 4, 5", "C": "1, 3, 6", "D": "2, 4, 6", "E": "2, 3, 6"}', 'A', '3', 'Altı aylıq qız uşağının yumurtalıqlarında yetişməmiş yumurtahüceyrələr olur , süd dişləri 6-7 ayından çıxmağa başlayır, qarışıq sekresiya vəziləri- mədəaltı vəzi və yumurtalıqları olur. İnkişafının postembrional dövrü (6 ay) embrional dövründən (9) qısadır.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №22', 'BIO-0052_izah.png'),
  ('BIO-0056', 'Ümumi biologiya', 'Hüceyrənin biokimyası', 'aciq_eded', 'DNT molekulunda azot əsaslarının əmələ gətirdiyi rabitələrin sayı hidrogen rabitələrinin ümumi sayı pentozaların əmələ gətirdiyi rabitələrin sayı 4400 2400 X X-i hesablayın.', 'BIO-0056.png', NULL::text, '5998', '3', 'Hər bir azot əsası DNT zənciri daxilində pentoza ilə 1, zəncirlərin arasında isə 2 və ya 3 hidrogen rabitəsi əmələ gətirir. Onda rabitələrin şərtdə verilən sayları arasındakı fərq elə pentozaların sayına bərabər olar (4400-2400=2000 pentoza). Hər bir pentoza 3 rabitənin (azotlu əsasla, aid olduğu nukleotidin və qonşu nukleotidin ortofosfat qalığı ilə) yaranmasında iştirak edir. Yalnız DNT molekulunun 2 ucunda yerləşən cəmi iki pentoza 2 rabitə əmələ gətirir. Ona görə də bu DNT molekulunda pentozaların əmələ gətirdiyi rabitələrin sayı 2000x3-2=5998 olar.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №26', 'BIO-0056_izah.png'),
  ('BIO-0060', 'Botanika', 'Vegetativ orqanlar', 'qapali', 'Qrafikdə çiçəkli bitkinin transpirasiyasının intensivliyinin zamandan asılılığı verilmişdir. Bu qrafikə əsasən doğru olan fikirləri müəyyən edin. t₁ → t₂ t³ zaman transpirasiyanın intensivliyi 0 1. 0-t₁ zaman aralığında yarpaqlarda ağızcıqlar açıq olmuşdur 2. t₁-t₂ zaman aralığında hava küləkli olmuşdur 3. bitki 0-t₁ və t₂-t₃ zaman aralıqlarında yalnız fotosintez etmişdir 4. t₁-t₂ zaman aralığında havanın rütubəti çox olmuşdur 5. 0-t₁ və t₂-t₃ zaman aralıqlarında torpaqdan udulan suyun miqdarı artmışdır', 'BIO-0060.png', '{"A": "1, 3", "B": "1, 4, 5", "C": "3, 4, 5", "D": "1, 2", "E": "2, 4, 5"}', 'B', '3', 'Küləkli havada transpirasiyanın intensivliyi artır, rütubətli havada isə azalır. t₁-t₂ zaman aralığında qrafikdə intensivliyin azaldığı müşahidə olunur. Bitkilərdə tənəffüs daima gedir. Bu səbəbdən heç bir zaman kəsiyində yalnız fotosintezin baş verməsi mümkün deyil. Ağızcıqlar açıq olduqda və torpaqdan udulan suyun miqdarı artdıqda transpirasiyanın intensivliyi artır (0-t₁ və t₂-t₃).', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №1', 'BIO-0060_izah.png'),
  ('BIO-0061', 'Botanika', 'Örtülütoxumlular şöbəsi', 'qapali', 'Verilən bitkilərin çiçəyindəki erkəkciklərin sayının artması ardıcıllığını müəyyən edin. 1. lobya 2. quşəppəyi 3. qarğıdalı 4. tütün', NULL::text, '{"A": "2, 1, 4, 3", "B": "3, 4, 1, 2", "C": "2, 1, 3, 4", "D": "3, 4, 2, 1", "E": "4, 3, 2, 1"}', 'D', '3', 'Lobya bitkisinin çiçəyində 10, quşəppəyi bitkisinin çiçəyində 6, qarğıdalı bitkisinin çiçəyində 3, tütün bitkisinin çiçəyində isə 5 erkəkcik olur.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №2', 'BIO-0061_izah.png'),
  ('BIO-0062', 'Zoologiya', 'Heyvanlar aləminin inkişafı', 'qapali', 'Uyğunluğu müəyyən edin. 1. Postembrional inkişaf dövründə qan dövranlarının sayı artır 2. Onurğası iki şöbədən ibarətdir 3. Erkək fərdləri homoqametdir a. göl qurbağası b. Asiya bəbiri c. təlxə d. xanı balığı e. dəniz tısbağası', NULL::text, '{"A": "1 – a, b; 2 – d; 3 – c, e", "B": "1 – c, d; 2 – e; 3 – a, b", "C": "1 – a, c; 2 – d; 3 – e", "D": "1 – b; 2 – c, d; 3 – a, e", "E": "1 – a; 2 – d; 3 – c, e"}', 'E', '3', 'Qurbağanın postembrional dövrünün əvvəlində 1, sonra isə 2 qan dövranı olur. Xanı balığının onurğası 2 şöbədən (gövdə və quyruq) ibarətdir. Sürünənlərdə dişilər XY, erkəklər isə XX cinsi xromosomlara malik olur. Təlxə və dəniz tısbağası sürünənlərə aid olduğu üçün onlarda erkəklər homoqametdir. Asiya bəbirində postembrional dövrdə qan dövranlarının sayı dəyişmir, onurğası beş şöbədən ibarətdir, erkəkləri heteroqametdir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №3', 'BIO-0062_izah.png'),
  ('BIO-0063', 'Ümumi biologiya', 'Hüceyrənin biokimyası', 'qapali', 'Bir polipeptidin sintezində istifadə olunan aminturşu sayını hesablamaq üçün bilmək lazımdır: 1. mRNT-dəki kodon sayını 2. gendə nukleotid sayını 3. yaranan peptid rabitələrin sayını 4. translyasiya prosesində iştirak edən nRNT-nin müxtəliflik sayını 5. ribosomların sayını', NULL::text, '{"A": "2, 3, 5", "B": "1, 2, 3", "C": "1, 2, 4", "D": "2, 4, 5", "E": "1, 3, 5"}', 'B', '3', 'Polipeptid zəncirini əmələ gətirən aminturşuların sayını onu kodlaşdıran mRNT-dəki kodonların, gendəki nukleotidlərin və yaranan peptid rabitələrin sayını bilməklə hesablamaq olar.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №4', 'BIO-0063_izah.png'),
  ('BIO-0064', 'Zoologiya', 'Qurdlar və molyusklar', 'qapali', 'X – insan askaridinin nazik bağırsaqda yumurtadan çıxan sürfəsidir. Bu inkişaf mərhələsi üçün doğru kəsişmələri müəyyən edin. həm arteriya, həm də vena damarlarında rast gəlinə bilər 1 normal miqrasiya zamanı həm arterial, həm də venoz qan ilə daşınır 2 adətən ürəyin yalnız sağ hissəsində rast gəlinir 4 3 diafraqma dəliyindən ağciyər venası və qarın aortası ilə keçir X', 'BIO-0064.png', '{"A": "1, 3", "B": "yalnız 2", "C": "1, 4", "D": "yalnız 3", "E": "2, 4"}', 'C', '3', 'Normal miqrasiya zamanı insan askaridinin cavan sürfəsi insanın kiçik qan dövranının arteriya damarında (ağciyər arteriyası – venoz qan), böyük qan dövranının isə vena damarlarında (bağırsaq venası, aşağı boş vena – venoz qan) olur. Beləliklə, yalnız venoz qan vasitəsilə miqrasiya etdiyinə görə ürəyin sağ hissəsində rast gəlinir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №5', 'BIO-0064_izah.png'),
  ('BIO-0065', 'İnsan anatomiyası və fiziologiyası', 'İfrazat sistemi və dəri', 'qapali', 'Cədvəldə sağlam insanın böyrək damarları ilə axan qanın tərkibində olan bəzi maddələrin miqdarının müqayisəsi göstərilmişdir. Buna əsasən hansı fikirlər doğrudur? Böyrək damarları Karbon qazı Mineral duzlar və sidik cövhəri Oksigen qazı X azdır çoxdur çoxdur Y çoxdur azdır azdır 1. Y damarı ilə axan qanın tərkibində zərərli maddələr az olur 2. X damarı ilə axan qan bilavasitə aşağı boş venaya tökülür 3. Y damarı qanı bilavasitə qarın aortasından alır 4. X damarı ilə bir dəqiqədə böyrəyə 0,5 l qan gələ bilər 5. Y damarı ilə axan qan aşağı boş venaya tökülür', 'BIO-0065.png', '{"A": "3, 4, 5", "B": "1, 4, 5", "C": "1, 2, 5", "D": "2, 3, 4", "E": "1, 2, 3"}', 'B', '3', 'X damarı – böyrək arteriyasıdır, bilavasitə qarın aortasından başlanğıc götürür və 1 dəqiqədə böyrəyə 0,5 litr qan gətirir. Bu damarla axan qan bilavasitə böyrək kapilyarlarına keçir. Y damarı – böyrək venasıdır, qan qarın aortasından deyil, böyrək kapilyarlarından bu damara keçir. Y damarı böyrəklərdə zərərli maddələrdən təmizlənmiş qanı bilavasitə aşağı boş venaya gətirir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №6', 'BIO-0065_izah.png'),
  ('BIO-0066', 'Botanika', 'Generativ orqanlar', 'qapali', 'Paxlanın meyvəyanlığı necə adlanır?', NULL::text, '{"A": "buynuzmeyvə", "B": "toxumca", "C": "arakəsmə", "D": "taycıqlar", "E": "qabıq"}', 'D', '3', 'Paxlanın meyvəsi paxlameyvədir. Paxlameyvənin meyvəyanlığı 2 taycıqdan ibarətdir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №7', 'BIO-0066_izah.png'),
  ('BIO-0067', 'Ümumi biologiya', 'Təkamül və həyatın əmələ gəlməsi', 'qapali', 'Sxemə əsasən X, Y, Z ola bilər: Ekoloji növəmələgəlmə Areal parçalanır Bəli Bəli Xeyr Xeyr X K Y Z Bəli Xeyr Areal dəyişmir', 'BIO-0067.png', '{"A": "X – qara arıquşu; Y – Qış beresi ; Z – qaiçka", "B": "X – daur qaraşamı; Y – abıca; Z – kəkilli arıquşu", "C": "X – kəkilli arıquşu; Y – inciciçəyinin növləri; Z – daur qaraşamı", "D": "X – qaiçka; Y – abıca; Z – kəkilli arıquşu", "E": "X – inciçiçəyinin növləri; Y – daur qaraşamı; Z – Qarabağ atı"}', 'C', '3', 'X – arealın dəyişməməsi ilə gedən, ekoloji növəmələgəlmə yolu ilə yaranan növdür (kəkilli arıquşu). Y – arealın parçalanması ilə yaranan növdür (inciçiçəyinin növləri). Z – arealın genişlənməsi ilə yaranan növ ola bilər (Daur qaraşamı). Qış beresi və Qarabağ atı növəmələgəlmə olmayıb, süni seçmənin (seleksiyanın) nəticəsində yaranıb.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №8', 'BIO-0067_izah.png'),
  ('BIO-0068', 'Ümumi biologiya', 'Mövzulararası əlaqə', 'qapali', 'Diploid (2n) xromosom sayı 80 olan dişi göyərçində mitoz bölünmə zamanı: Bölünməyə məruz qalan başlanğıc hüceyrələrin sayı Anafazada X cinsi xromosomların cəmi Anafazada autosom xromosomların cəmi 4 A B B–A fərqini hesablayın.', 'BIO-0068.png', '{"A": "632", "B": "608", "C": "616", "D": "308", "E": "312"}', 'C', '3', '2n = 80. Bunlardan 78-i autosom, 2-si isə XY olmaqla cinsi xromosomlardır. Mitozun anafazasında xromosom sayı 2 dəfə artdığı üçün: 78x2=156 autosom və 2X və 2Y cinsi xromosomu müşahidə olunur. Deməli, 4 hüceyrə üçün A=2x4=8, B=156x4=624. B – A = 624 – 8 = 616.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №9', 'BIO-0068_izah.png'),
  ('BIO-0069', 'Botanika', 'Bitki aləminin inkişafı', 'qapali', 'Cədvəldə örtülütoxumlular hansı rəqəmlə göstərilmişdir? Bitki qrupu Quruluşu Yayıldığı mühit Cinsi çoxalmasında suyun vacibliyi Bir- hücey- rəli Çox- hücey- rəli Su Quru 1 + + + + + 2 – + + + + 3 – + – + – 4 – + + + –', 'BIO-0069.png', '{"A": "yalnız 2", "B": "1, 4", "C": "1, 3", "D": "2, 3", "E": "yalnız 4"}', 'E', '3', 'Örtülütoxumlular yalnız çoxhüceyrəli olur. Onların suda və quruda yaşayan nümayəndələri məlumdur. Bu bitkilərin cinsi çoxalması üçün suya ehtiyac olmur.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №10', 'BIO-0069_izah.png'),
  ('BIO-0070', 'Ümumi biologiya', 'Çoxalma və inkişaf', 'qapali', 'Erkək fərdləri heteroqamet olan diploid ikievli çiçəkli bitki toxumunun endosperminin genotipi XXY olarsa, bu toxumdan əmələ gələn bitkidə:', NULL::text, '{"A": "tozcuq borusu yarana bilər", "B": "yalnız mikrosporlar yaranar", "C": "ikicinsli çiçəklər olar", "D": "ikiqat mayalanma gedə bilər", "E": "yalnız dişicikli çiçəklər olar"}', 'B', '3', 'İkievli bitki bircinsli olur. Şərtə əsasən bitki erkək heteroqametli olduğu üçün XXY genotipli endospermə malik toxumdan yalnız erkək bitkilər əmələ gələ bilər. Bu bitkilərin çiçəklərində yalnız tozcuq dənələri, onlarda da mikrosporlar yaranır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №11', 'BIO-0070_izah.png'),
  ('BIO-0071', 'Botanika', 'Bakteriyalar və göbələklər', 'qapali', 'Uyğunluğu müəyyən edin. Bakteriya formaları: 1. 2. 3 Onların törətdiyi xəstəliklər: a. vəba b. difteriya c. angina d. sibir yarası e. taun', 'BIO-0071.png', '{"A": "1 – a; 2 – b, c, e; 3 – d", "B": "1 – a, c; 2 – b, d; 3 – e", "C": "1 – c; 2 – b, d, e; 3 – a", "D": "1 – d; 2 – a, e; 3 – b, c", "E": "1 – c; 2 – b, e; 3 – a, d"}', 'C', '3', 'Vəba xəstəliyinin törədicisi vibriondur (3), angina xəstəliyinin törədicisi kokklardır (1), difteriya, sibir yarası və taun xəstəliklərinin törədiciləri isə basillərdir (2).', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №12', 'BIO-0071_izah.png'),
  ('BIO-0072', 'İnsan anatomiyası və fiziologiyası', 'Dayaq-hərəkət sistemi', 'qapali', 'İnsan skeletində dik gəzməklə əlaqədar deyil:', NULL::text, '{"A": "ayağın altının tağ şəklində olması", "B": "oma sümüyünün möhkəmlənməsi", "C": "onurğada 4 əyriliyin əmələ gəlməsi", "D": "kəllənin üz şöbəsinin beyin şöbəsindən kiçik olması", "E": "döş qəfəsinin yanlara doğru genişlənməsi"}', 'D', '3', 'Kəllənin üz şöbəsinin beyin şöbəsindən kiçik olması dik gəzməklə deyil, baş beynin inkişafı ilə əlaqəlidir. Dik yerimə nəticəsində insanın skeletində oma sümüyü möhkəmlənmiş, döş qəfəsi yanlara doğru genişlənmiş, onurğasında 4 əyrilik və tağşəkilli ayaq altı əmələ gəlmişdir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №13', 'BIO-0072_izah.png'),
  ('BIO-0073', 'Zoologiya', 'İbtidailər və bağırsaqboşluqlular', 'qapali', 'Şirin su hidrasına aid düzgün fikirləri müəyyən edin. 1. Ektoderma qatında fərqli xromosom yığımına malik hüceyrələrə rast gəlinə bilər 2. Somatik mutasiyalar irsən nəsilə ötürülə bilər 3. Yumurtahüceyrəsi hərəkətsizdir 4. Qamçılı hüceyrələrinin hamısı eyni funksiya daşıyır 5. Həzm hüceyrələrinin və dəri-əzələ hüceyrələrinin xromosom yığımı eyni olur', NULL::text, '{"A": "1, 3, 4", "B": "2, 3, 4", "C": "2, 4, 5", "D": "1, 2, 5", "E": "1, 3, 5"}', 'D', '3', 'Hidranın xarici qatında somatik hüceyrələr diploid, cinsi hüceyrələr isə haploid xromosom yığımına malikdir. Hidra tumurcuqlanma yolu ilə çoxala bildiyi üçün, onda yaranan somatik mutasiyalar irsən nəsilə ötürülə bilər. Həzm və dəri-əzələ hüceyrələri somatik hüceyrə olduğu üçün onların hər ikisində eyni xromosom yığımı olur. Yumurtahüceyrəsində yalançı ayaqlar olduğu üçün, o, hərəkətlidir. Həzm və cinsi hüceyrələr qamçılara malik olduğu üçün onlar fərqli funksiyalar yerinə yetirir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №14', 'BIO-0073_izah.png'),
  ('BIO-0074', 'Zoologiya', 'Xordalılar, balıqlar, suda-quruda yaşayanlar, sürünənlər', 'qapali', 'Qurbağanın skeletində yoxdur:', NULL::text, '{"A": "əsl qabırğalar", "B": "baldır sümükləri", "C": "quyruq sümüyü", "D": "qarğa sümükləri", "E": "döş sümüyü"}', 'A', '3', 'Qurbağada döş qəfəsi olmadığı üçün onda əsl qabırğalar yoxdur. Digər sümüklər onun skeletində var.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №15', 'BIO-0074_izah.png'),
  ('BIO-0075', 'İnsan anatomiyası və fiziologiyası', 'Qan, qan dövranı, tənəffüs', 'qapali', 'A-dan B-yə keçid hansı halda doğrudur? bütün kapilyarlar alveol kapilyarları 2 ağciyər → venası 3 əzələ kapilyarları 4 aorta 5 venoz → qan arterial qan A B', 'BIO-0075.png', '{"A": "1 və 5", "B": "yalnız 4", "C": "3 və 5", "D": "yalnız 1", "E": "2 və 4"}', 'B', '3', 'Venoz qan yalnız ağciyər alveollarında arterial qana çevrilir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №16', 'BIO-0075_izah.png'),
  ('BIO-0076', 'Ümumi biologiya', 'Sitologiya', 'qapali', 'Hansı mülahizə xloroplastlar üçün doğrudur?', NULL::text, '{"A": "daxili membranı kristlər əmələ gətirir", "B": "nuklein turşularından yalnız RNT-yə rast gəlinir", "C": "hüceyrə tənəffüsünü təmin edir", "D": "membransız orqanoidi olmur", "E": "daxili möhtəviyyatı stroma adlanır"}', 'E', '3', 'Xloroplastların daxili membranı qranlar əmələ gətirir, burada DNT və RNT, membransız orqanoidlər olan ribosomlara rast gəlinir, möhtəviyyatı isə stroma adlanır. Hüceyrə tənəffüsünü mitoxondrilər yerinə yetirir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №17', 'BIO-0076_izah.png'),
  ('BIO-0077', 'Botanika', 'Yosunlar, mamırlar, qıjılar, çılpaqtoxumlular', 'qapali', 'Eyler-Venn diaqramına əsasən uyğun bəndləri müəyyən edin. X Z Y 1. Yetkin fərdi cinsiyyətli nəsil ola bilər 2. Yetkin fərdi spor əmələ gətirə bilər 3. Yetkin fərdi qamet əmələ gətirmir 4. Yetkin fərdlərində mitoz və meyoz bölünmə gedə bilər 5. “Süngər” adlanır X Y Z', 'BIO-0077.png', '{"A": "4, 5 1, 3", "B": "5 2, 3 1, 4", "C": "2, 4 1, 5", "D": "1, 5 3 2, 4", "E": "1, 3 5 2, 4"}', 'D', '3', 'X bitkisi sfaqnumdur, Y bitkisi isə erkək qıjıdır. Sfaqnumun yetkin fərdində həm qametlər, həm də sporlar əmələ gələ bilər. Sfaqnum “süngər” adlanır. Qıjıların yetkin fərdi qamet əmələ gətirmir. Həm sfaqnum, həm də erkək qıjının yetkin fərdində sporlar əmələ gəldiyinə görə, onlarda mitoz və meyoz bölunmə gedə bilər.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №18', 'BIO-0077_izah.png'),
  ('BIO-0078', 'Ümumi biologiya', 'Ekologiya və biosfer', 'qapali', 'Ekoloji piramidada canlılar hərflərlə verilmişdir. L K F N M Piramidaya əsasən hansı mülahizələr doğrudur? 1. N canlısı üzərinə düşən Günəş enerjisinin 1%-dən istifadə edir 2. M canlısı atmosferi oksigenlə zənginləşdirə bilər 3. L canlısı yırtıcı ola bilər 4. F canlısı II dərəcəli konsumentdir 5. K canlısında olan enerjinin 5-20%-i F canlısına keçir', 'BIO-0078.png', '{"A": "2, 3, 4", "B": "1, 3, 4", "C": "1, 2, 5", "D": "3, 4, 5", "E": "1, 2, 3"}', 'A', '3', 'M canlısı produsent olduğu üçün atmosferi oksigenlə zənginləşdirə bilər. L canlısı piramidanın zirvəsində yerləşdiyinə görə yırtıcı ola bilər. F canlısı II dərəcəli konsumentdir. N canlısı konsument olduğu üçün Günəş enerjisindən istifadə etmir. K canlısından F canlısına enerji keçə bilməz.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №19', 'BIO-0078_izah.png'),
  ('BIO-0079', 'Zoologiya', 'Buğumayaqlılar', 'qapali', 'Xaçlı hörümçəyin baş-döş hissəsində yerləşən orqanlar: 1. zəhər vəzisi 2. mədə 3. tor vəziləri 4. ürək 5. xeliser 6. cinsiyyət vəzisi', NULL::text, '{"A": "2, 5, 6", "B": "1, 3, 4", "C": "2, 4, 6", "D": "3, 5, 6", "E": "1, 2, 5"}', 'E', '3', 'Xaçlı hörümçəyin baş-döş hissəsində zəhər vəzisi, mədə və xeliserlər yerləşir. Tor vəziləri, ürək və cinsiyyət vəzisi qarıncıqda yerləşir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №20', 'BIO-0079_izah.png'),
  ('BIO-0080', 'Ümumi biologiya', 'Genetika', 'qapali', 'Uyğunluğu müəyyən edin. 1. I qan qrupu 2. III qan qrupu a. iki cür genotipli ola bilər b. plazmasında anti-A və anti-B antitelləri (anticisimləri) olan qan qrupuna malik insana donor ola bilər c. eritrositlərində yalnız B antigeni olur d. eritrositlərində yalnız antigen A olan qan qrupuna malik insana donor ola bilər e. plazmasında yalnız anti-B antiteli (anticismi) olan qan qrupuna malik insana donor ola bilər', NULL::text, '{"A": "1 – b, d, e; 2 – a, c", "B": "1 – b, d; 2 – a, c, e", "C": "1 – c, e; 2 – a, b, d", "D": "1 – a, c; 2 – b, d, e", "E": "1 – a, c, e; 2 – b, d"}', 'A', '3', 'I qan qrupunun eritrositlərində antigen olmur, plazmasında isə anti-A və anti-B anticisimləri olur. Bu səbəbdən bütün qan qruplarına donor ola bilir və bir genotipi (OO) olur. III qan qrupunun genotipi BB və ya BO ola bilər, eritrositlərində B antigeni, plazmasında isə anti-A anticisimləri olur. III qan qrupu özünə və IV qan qrupuna donor ola bilər. Eritrositlərində yalnız antigen A və plazmasında yalnız anti-B antiteli (anticismi) olan qan qrupu II qan qrupu olduğu üçün, ona III qan qrupu deyil, I qan qrupuna malik insan donor ola bilər.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №21', 'BIO-0080_izah.png'),
  ('BIO-0081', 'Ümumi biologiya', 'Çoxalma və inkişaf', 'qapali', 'X-də baş verir: 1. Aybaşı tsiklinin ikinci fazası 2. Mayalanma 3. Döl dövrünün başlanması 4. Sarı cismin əmələ gəlməsi', 'BIO-0081.png', '{"A": "1, 4", "B": "1, 3", "C": "2, 4", "D": "2, 3", "E": "1, 2"}', 'A', '3', 'X – yumurtalıqdır. Burada aybaşı tsiklinin bütün fazaları baş verir, o cümlədən də sarı cisim əmələ gəlir. Mayalanma uşaqlıq borusunda, döl dövrü isə uşaqlıqda başlayır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №22', 'BIO-0081_izah.png'),
  ('BIO-0084', 'Zoologiya', 'Quşlar və məməlilər', 'aciq_eded', 'Məməli bir heyvanın döş qəfəsində 34 sümük olsa, onun skeletinin bu hissəsindəki tək sümüklərin sayı cüt sümüklərin sayından nə qədər az olar?', NULL::text, NULL::text, '10', '3', 'Məməlilərin döş qəfəsi 1 döş sümüyündən, cüt qabırğalardan və döş fəqərələrindən təşkil olunub. 3x+1=34 3x=33 x=11 Deməli, 11 fəqərə və 1 döş sümüyü – tək sümüklərdir, 22 qabırğa – cüt sümüklərdir. 22-12=10', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №25', 'BIO-0084_izah.png'),
  ('BIO-0090', 'Botanika', 'Yosunlar, mamırlar, qıjılar, çılpaqtoxumlular', 'qapali', 'Qıjı, qatırquyruğu və plaunların oxşar cəhətləri:', NULL::text, '{"A": "meyvəkök", "B": "yetkin forması – qametofit", "C": "mil kök sistemi", "D": "saçaqlı kök sistemi", "E": "toxumla çoxalma"}', 'D', '3', 'Qıjı, qatırquyruğu və plaunların oxşar cəhətləri saçaqlı kök sisteminin olmasıdır (onlarda əlavə kök və yan köklər var).', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №1', 'BIO-0090_izah.png'),
  ('BIO-0091', 'Ümumi biologiya', 'Sitologiya', 'qapali', 'Hansı canlılarda hüceyrə divarına rast gəlinər? 1. Parmeliya 2. Lyambliya 3. Sianobakteriya 4. Plevrakokk 5. Amöb', NULL::text, '{"A": "2, 4", "B": "1, 4, 5", "C": "1, 3, 4", "D": "2, 5", "E": "1, 3, 5"}', 'C', '3', 'Hüceyrə divarına parmeliyada (şibyə), sianobakteriyada (bakteriya) və plevrakokkda (bitki) rast gəlinir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №2', 'BIO-0091_izah.png'),
  ('BIO-0092', 'Botanika', 'Vegetativ orqanlar', 'qapali', 'Ağac gövdəsinin quruluş sxemi üçün uyğunluğu müəyyən edin. 2 3 1 a. qeyri-üzvi maddələri daşıyan borucuqlar yerləşir b. gövdənin eninə böyüməsini təmin edir c. qabıq və oduncaq hüceyrələri yaradır d. illik halqalar yerləşir e. mərciməklər yerləşir', 'BIO-0092.png', '{"A": "1 – e; 2 – b; 3 – a, c, d", "B": "1 – a, e; 2 – b, c; 3 – d", "C": "1 – b; 2 – c, e; 3 – a, d", "D": "1 – e; 2 – b, c; 3 – a, d", "E": "1 – c, e; 2 – b, d; 3 – a"}', 'D', '3', '1 - mantar (burada mərciməklər yerləşir) 2 - kambi ( gövdənin eninə böyüməsini təmin edir, qabıq və oduncaq hüceyrələri yaradır) 3 - oduncaq (burada qeyri-üzvi maddələri daşıyan borucuqlar (ksilema borucuqları) yerləşir. )', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №3', 'BIO-0092_izah.png'),
  ('BIO-0093', 'Zoologiya', 'Qurdlar və molyusklar', 'qapali', 'Həzm sistemi yalnız bir dəliklə xarici mühitlə əlaqəli olanlar:', NULL::text, '{"A": "ağ planari və nereid", "B": "soxulcan və ağ planari", "C": "soxulcan və insan askaridi", "D": "insan askaridi və öküz soliteri", "E": "ağ planari və qaraciyər sorucusu"}', 'E', '3', 'Həzm sistemi yalnız bir dəliklə (ağızla) xarici mühitlə əlaqəli olan canlılar - yastı qurdlardır (ağ planari və qaraciyər sorucusu).', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №4', 'BIO-0093_izah.png'),
  ('BIO-0094', 'Ümumi biologiya', 'Ekologiya və biosfer', 'qapali', 'Uyğunluğu müəyyən edin. 1. Produsent 2. Redusent a. üzvi maddələri minerallaşdırır b. fitoplankton c. yalnız heterotrof qidalanır d. sürmə göbələyi e. hidrogen bakteriyası', NULL::text, '{"A": "1 – a, c; 2 – b, d, e", "B": "1 – b, e; 2 – a, c", "C": "1 – b; 2 – a, c, e", "D": "1 – a, b, d; 2 – c, e", "E": "1 – b, d, e; 2 – a, c"}', 'B', '3', 'Produsent - fitoplankton (fotosinezedici), hidrogen bakteriyası(xemosinezedici). Redusent - üzvi maddələri minerallaşdırır (saprofit) və yalnız heterotrof qidalanır.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №5', 'BIO-0094_izah.png'),
  ('BIO-0096', 'Botanika', 'Bitki aləminin inkişafı', 'qapali', 'Eyler-Venn diaqramına əsasən uyğun bəndləri müəyyən edin. Yaşıl çiçəkli söyüd Adi şam 1 2 3 a. mayalanma baş verir b. üç növ generativ orqana malikdir c. tozcuq kisələri var d. tozlanma baş verir e. üç növ vegetativ orqana malikdir', 'BIO-0096.png', '{"A": "1 – b; 2 – c; 3 – a, d, e", "B": "1 – b; 2 – a, d; 3 – c, e", "C": "1 – a, b; 2 – c; 3 – d, e", "D": "1 – d; 2 – c, e; 3 – a, b", "E": "1 – e; 2 – a; 3 – b, c, d"}', 'A', '3', 'Yaşıl çiçəkli söyüddə (dişi bitki) və adi şamda (çılpaqtoxumlu) tozlanma və mayalanma prosesi baş verir. Hər ikisi 3 vegetativ orqana (kök, gövdə, yarpaq) malikdir. Yaşıl çiçəkli söyüddə 3 növ generativ orqan (çiçək, meyvə, toxum), adi şamda isə tozcuq kisələri var.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №7', 'BIO-0096_izah.png'),
  ('BIO-0097', 'Ümumi biologiya', 'Mövzulararası əlaqə', 'qapali', 'Sxemdə verilmiş proseslərlə bağlı hansı mülahizə sağlam insan üçün yanlışdır? aminturşusu CO₂+H₂O+azotlu birləşmələr zülal → 2 1 3', 'BIO-0097.png', '{"A": "3 – bilavasitə ağız boşluğunda baş verir", "B": "1 – həzm kanalında baş verir", "C": "1 – katabolik prosesdir", "D": "2 – ribosomlarda baş verir", "E": "2 – plastik mübadiləyə aiddir"}', 'A', '3', '1 - zülalın parçalanmasıdır, həzm kanalında baş verir və katabolik prosesdir. 2 - zülalın biosintezidir, plastik mübadiləyə aiddir və ribosomlarda baş verir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №8', 'BIO-0097_izah.png'),
  ('BIO-0098', 'İnsan anatomiyası və fiziologiyası', 'Sinir sistemi və analizatorlar', 'qapali', 'Mürəkkəb refleks qövsündə iştirak edən 3 müxtəlif növ neyron sinir impulsunu bir-birlərinə ötürür. Refleks qövsünün hansı hissəsində bu neyronların arasında sinapslar yarana bilər?', 'BIO-0098.png', '{"A": "yalnız M", "B": "N", "C": "Z", "D": "X", "E": "yalnız Y"}', 'C', '3', 'Mürəkkəb refleksdə 3 müxtəlif növ neyronun (hissi, ara, hərəki) bir-biri ilə yaratdığı sinapslar mərkəzi sinir sistemində (Z) yarana bilər.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №9', 'BIO-0098_izah.png'),
  ('BIO-0099', 'Zoologiya', 'Quşlar və məməlilər', 'qapali', 'Hansı mülahizə doğru deyil?', NULL::text, '{"A": "bəzi suda yaşayan məməlilərin tük örtüyü olmur", "B": "suda yaşayan məməlilər ağciyərlərlə tənəffüs edir", "C": "bəzi suda yaşayan məməlilər quruya çıxır", "D": "suda yaşayan məməlilər yalnız suda çoxalır", "E": "suda yaşayan məməlilər balalarını süd ilə bəsləyir"}', 'D', '3', 'Suda yaşayan məməlilər yalnız suda çoxalır fikri yanlışdır, məsələn suitinin çoxalması quruda baş verir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №10', 'BIO-0099_izah.png'),
  ('BIO-0100', 'İnsan anatomiyası və fiziologiyası', 'Qan, qan dövranı, tənəffüs', 'qapali', 'Ortayaşlı sağlam insanda bir dərin nəfəsalma zamanı normada neçə ml (sm³) oksigen ağciyər kapillyarlarına keçir?', NULL::text, '{"A": "300", "B": "100", "C": "75", "D": "250", "E": "25"}', 'B', '3', 'Dərin nəfəsalmada 500 ml (sm³) tənəffüs havası və 1500 ml (sm³) əlavə hava ağciyərlərə daxil olur. Kapilyarlara keçən oksigen qəbul olunan havanın 5% -dir. 500 +1500=2000 ml (sm³) 2000-100% X-5% X=100 ml (sm³)', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №11', 'BIO-0100_izah.png'),
  ('BIO-0101', 'İnsan anatomiyası və fiziologiyası', 'Həzm və maddələr mübadiləsi', 'qapali', 'Sxemdə verilmiş proses sağlam insanda harada baş verir? + yağ turşusu qliserin yağ', 'BIO-0101.png', '{"A": "yalnız yoğun bağırsaqda", "B": "nazik bağırsaqda", "C": "yalnız mədə və yoğun bağırsaqda", "D": "ağız boşluğunda", "E": "yalnız mədədə"}', 'B', '3', 'Yağların kimyəvi həzmi mədədə (süd yağı) və nazik bağırsaqda gedir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №12', 'BIO-0101_izah.png'),
  ('BIO-0102', 'Zoologiya', 'Heyvanlar aləminin inkişafı', 'qapali', 'Hansı mülahizə yanlışdır? Xəstəliklər Törədici Keçirici Ensefalit X Y Yuxu M N Taun Z K', 'BIO-0102.png', '{"A": "M və K eyni aləmə aiddir", "B": "Z və K müxtəlif aləmlərə aiddir", "C": "Y, N, K eyni aləmə aiddir", "D": "M və Z müxtəlif aləmlərə aiddir", "E": "X, M, Z eyni aləmə aiddir"}', 'E', '3', 'Xəstəliklər Törədici Keçirici Ensefalit Virus Gənə Yuxu Birhüceyrəli heyvan Milçək Taun Bakteriya Birə', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №13', 'BIO-0102_izah.png'),
  ('BIO-0103', 'Ümumi biologiya', 'Çoxalma və inkişaf', 'qapali', 'Sağlam qadının aybaşı tsiklinin fazalarında uşaqlıq divarının vəziyyəti təsvir olunmuşdur. Doğru mülahizələri müəyyən edin. I. Z sarı cisim fazasıdır II. Z fazasında yumurtahüceyrə uşaqlıq borusunda ola bilər III. X fazasının sonunda uşaqlığın divarı maksimal qalınlığa çatır IV. Ovulyasiya üçün ən əlverişli vaxt Z fazasının sonudur V. Y fazası 11 yaşlı qızda baş verə bilər', 'BIO-0103.png', '{"A": "I, II, IV", "B": "I, II, V", "C": "II, III, IV", "D": "I, IV, V", "E": "I, III, IV"}', 'B', '3', 'Z sarı cisim fazasıdır və bu fazada yumurtahüceyrə uşaqlıq borusunda ola bilər. Aybaşı tsikli qızlarda minimum 10 yaşında başladığına görə Y fazası 11 yaşlı qızda baş verə bilər.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №14', 'BIO-0103_izah.png'),
  ('BIO-0104', 'Ümumi biologiya', 'Genetika', 'qapali', 'Nəsil şəcərəsində insanların qan qruplarının fenotipləri verilmişdir. Rəqəmlərlə işarə olunmuş hansı insanın (insanların) qan qrupunun genotipini dəqiq təyin etmək olmaz? IV II II 1 2 III II 3 4 IV III', 'BIO-0104.png', '{"A": "yalnız 1", "B": "1, 2", "C": "3, 4", "D": "yalnız 2", "E": "1, 4"}', 'A', '3', 'IV II II 1 2 III II 3 4 IV III', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №15', 'BIO-0104_izah.png'),
  ('BIO-0105', 'Ümumi biologiya', 'Mövzulararası əlaqə', 'qapali', 'Ondatra hüceyrəsinin hansı orqanoidlərində zülalın biosintezi gedir?', NULL::text, '{"A": "Holci kompleksi, xloroplast", "B": "xloroplast, hamar endoplazmatik şəbəkə", "C": "mitoxondri, hamar endoplazmatik şəbəkə", "D": "ribosom, xloroplast", "E": "ribosom, mitoxondri"}', 'E', '3', 'Ondatra məməli heyvandır. Heyvan hüceyrələrində zülalın biosintezi ribosom və mitoxondrilərdə gedə bilər.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №16', 'BIO-0105_izah.png'),
  ('BIO-0107', 'Zoologiya', 'İbtidailər və bağırsaqboşluqlular', 'qapali', 'Bağırsaqboşluqlular tipinə aid canlılarda rast gəlinən şəkildəki hüceyrə haqqında verilən ifadələrdən hansı yanlışdır? 1 2', 'BIO-0107.png', '{"A": "aralıq hüceyrələrdən əmələ gəlir", "B": "vəzili hüceyrələr ilə eyni qatda yerləşə bilməz", "C": "bədənin hər iki qatında yerləşir", "D": "dəri-əzələ hüceyrələri ilə yanaşı yerləşə bilər", "E": "2-nin kapsuldan çıxması üçün 1 qıcıqlanmalıdır"}', 'C', '3', 'Bağırsaqboşluqlular tipinə aid canlılarda rast gəlinən şəkildəki hüceyrə - dalayacı hüceyrədir. Bu hüceyrə bədənin yalnız xarici qatında (ektodermada) yerləşir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №18', 'BIO-0107_izah.png'),
  ('BIO-0108', 'İnsan anatomiyası və fiziologiyası', 'Daxili sekresiya vəziləri', 'qapali', 'İnsanda hansı vəzilər yalnız xarici sekresiya vəzilərinə aiddir?', NULL::text, '{"A": "timus", "B": "qalxanabənzər", "C": "böyrəküstü", "D": "mədəaltı", "E": "mədə"}', 'E', '3', 'Mədə yalnız xarici sekresiya vəzilərinə aiddir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №19', 'BIO-0108_izah.png'),
  ('BIO-0109', 'Botanika', 'Bakteriyalar və göbələklər', 'qapali', 'Birhüceyrəli göbələklər: 1. 2. 3. 4. 5.', 'BIO-0109.png', '{"A": "4, 5", "B": "2, 3, 4", "C": "1, 2, 3", "D": "1, 4", "E": "1, 5"}', 'A', '3', 'Birhüceyrəli göbələklər 4 - mukor və 5 - maya göbələyi.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №20', 'BIO-0109_izah.png'),
  ('BIO-0114', 'Zoologiya', 'Buğumayaqlılar', 'aciq_eded', 'Müəyyən ərazidə yayılmış çay xərçəngi, xaçlı hörümçək və may böcəklərinin cəmi 620 yerimə ayaqları vardır. Bu heyvanlardan 48-i çay xərçəngidir. Xaçlı hörümçəklə may böcəyinin ətraflarının sayının 4:3 nisbətində olduğunu bilərək, burada neçə xaçlı hörümçək olduğunu hesablayın.', NULL::text, NULL::text, '10', '3', '48x10=480 ayaq (çay xərçənglərində) 620-480=140 ayaq (xaçlı hörümçəklər və may böcəkləri) 4x+3x=7x 7x=140 x=20 20x4=80 ayaq (xaçlı hörümçəklərdə) 80/8=10 xaçlı hörümçək', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №25', 'BIO-0114_izah.png')
       ) as v(code, section, topic, type, body, image_path, options, correct, difficulty, solution,
              groups, year, source_ref, solution_image_path)
  join subjects s on s.slug = 'biologiya'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = v.section
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = v.topic
on conflict (code) do update set
  topic_id = excluded.topic_id, type = excluded.type, body = excluded.body, image_path = excluded.image_path,
  options = excluded.options, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty,
  solution = excluded.solution, exam_levels = excluded.exam_levels, groups = excluded.groups,
  year = excluded.year, source = excluded.source, source_ref = excluded.source_ref,
  is_active = excluded.is_active, solution_image_path = excluded.solution_image_path;

-- 4) every approved question must now exist (a missing topic would silently drop a row from the join)
do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('BIO-0001', 'BIO-0002', 'BIO-0003', 'BIO-0004', 'BIO-0006', 'BIO-0007', 'BIO-0008', 'BIO-0009', 'BIO-0010', 'BIO-0011', 'BIO-0013', 'BIO-0014', 'BIO-0015', 'BIO-0016', 'BIO-0017', 'BIO-0018', 'BIO-0019', 'BIO-0020', 'BIO-0021', 'BIO-0024', 'BIO-0031', 'BIO-0032', 'BIO-0033', 'BIO-0034', 'BIO-0036', 'BIO-0038', 'BIO-0039', 'BIO-0040', 'BIO-0042', 'BIO-0044', 'BIO-0045', 'BIO-0046', 'BIO-0047', 'BIO-0048', 'BIO-0049', 'BIO-0050', 'BIO-0051', 'BIO-0052', 'BIO-0056', 'BIO-0060', 'BIO-0061', 'BIO-0062', 'BIO-0063', 'BIO-0064', 'BIO-0065', 'BIO-0066', 'BIO-0067', 'BIO-0068', 'BIO-0069', 'BIO-0070', 'BIO-0071', 'BIO-0072', 'BIO-0073', 'BIO-0074', 'BIO-0075', 'BIO-0076', 'BIO-0077', 'BIO-0078', 'BIO-0079', 'BIO-0080', 'BIO-0081', 'BIO-0084', 'BIO-0090', 'BIO-0091', 'BIO-0092', 'BIO-0093', 'BIO-0094', 'BIO-0096', 'BIO-0097', 'BIO-0098', 'BIO-0099', 'BIO-0100', 'BIO-0101', 'BIO-0102', 'BIO-0103', 'BIO-0104', 'BIO-0105', 'BIO-0107', 'BIO-0108', 'BIO-0109', 'BIO-0114');
  if n <> 81 then
    raise exception 'Gözlənilən 81 sual, bazada % tapıldı: geri alınır', n;
  end if;
end $$;

commit;

-- 5) result
select s.name as fenn, count(*) as sual_sayi
  from questions q
  join topics t on t.id = q.topic_id
  join subjects s on s.id = t.subject_id
 where s.slug = 'biologiya' and q.source = 'DİM'
 group by s.name;
